+function fire(){if(player.shootCd>0)return;if(player.ammo<=0){toast('MAGAZINE EMPTY · PRESS R');player.shootCd=.28;audio(90,.05,'square',.012);return}player.ammo--;player.shootCd=.18;player.flash=.08;audio(115,.075,'sawtooth',.045);let sx=player.x+Math.cos(player.angle)*17,sy=player.y+Math.sin(player.angle)*17,spread=(Math.random()-.5)*.045,ang=player.angle+spread;bullets.push({x:sx,y:sy,vx:Math.cos(ang)*730,vy:Math.sin(ang)*730,life:.65,owner:'player',damage:26});fx.push({x:sx,y:sy,life:.12,type:'muzzle',a:ang});for(let e of enemies){if(e.dead)continue;let dx=e.x-sx,dy=e.y-sy,along=dx*Math.cos(ang)+dy*Math.sin(ang),side=Math.abs(-dx*Math.sin(ang)+dy*Math.cos(ang));if(along>0&&along<470&&side<e.r+7){e.hp-=26;e.state='alert';e.alert=5;fx.push({x:e.x,y:e.y,life:.28,type:'blood'});if(e.hp<=0){e.dead=true;player.ru+=e.faction==='Bandits'?80:0;showFeed('✕  '+e.name.toUpperCase()+' DOWN · '+e.faction.toUpperCase());audio(70,.14,'triangle',.04)}else audio(55,.08,'sine',.02);break}}}
+function update(dt){if(!gameStarted||paused||dead||won)return;elapsed+=dt;player.shootCd=Math.max(0,player.shootCd-dt);player.flash=Math.max(0,player.flash-dt);player.invuln=Math.max(0,player.invuln-dt);if(toastTimer>0&& (toastTimer-=dt)<=0)$('toast').classList.remove('visible');if(bannerTimer>0&&(bannerTimer-=dt)<=0)$('objective-banner').classList.remove('show');let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+input.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+input.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}let sprint=keys.shift||input.sprint,speed=player.speed*(sprint?1.52:1);player.x=clamp(player.x+dx*speed*dt,35,W-35);player.y=clamp(player.y+dy*speed*dt,35,H-35);if(Math.abs(dx)+Math.abs(dy)>.05)player.angle=Math.atan2(dy,dx);let worldMouse={x:mouse.x+camera.x,y:mouse.y+camera.y};if(mouse.x||mouse.y)player.angle=Math.atan2(worldMouse.y-player.y,worldMouse.x-player.x);if(mouse.down||input.fire)fire();
