+    if(hostile&&d<300&&Math.random()<dt*.55){let a=Math.atan2(player.y-e.y,player.x-e.x);bullets.push({x:e.x,y:e.y,vx:Math.cos(a)*310,vy:Math.sin(a)*310,life:1.2,owner:'enemy',damage:e.type==='mutant'?12:8});e.state='hunt';e.alert=3}
+  }
+  for(let b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.owner==='enemy'&&dist(b,player)<player.r+4&&player.invuln<=0){b.life=0;player.hp-=b.damage;player.invuln=.32;$('hit-flash').classList.add('active');setTimeout(()=>$('hit-flash').classList.remove('active'),130);audio(68,.12,'sawtooth',.04);if(player.hp<=0)endGame(false)}else if(b.owner==='player'){for(let e of enemies){if(!e.dead&&dist(b,e)<e.r+3){b.life=0;e.hp-=b.damage;if(e.hp<=0){e.dead=true;showFeed('✕  '+e.name.toUpperCase()+' DOWN')}break}}}}
+  for(let f of fx)f.life-=dt;for(let i=bullets.length-1;i>=0;i--)if(bullets[i].life<=0)bullets.splice(i,1);for(let i=fx.length-1;i>=0;i--)if(fx[i].life<=0)fx.splice(i,1);
+  let danger=dist(player,{x:1540,y:1100});player.rad=clamp(player.rad+(danger<210?dt*1.1:-dt*.35),0,100);if(player.rad>60&&Math.random()<dt*.28){player.hp=Math.max(1,player.hp-1);toast('RADIATION EXPOSURE · FIND COVER')}
+  if(artifact.found&&dist(player,{x:420,y:1480})<100){won=true;endGame(true)}
+  let near=false;for(let s of stash)if(!s.searched&&dist(player,s)<72){near=true;$('interaction-prompt').querySelector('span').textContent='SEARCH '+s.kind;break}if(!near&&!artifact.found&&dist(player,artifact)<92){near=true;$('interaction-prompt').querySelector('span').textContent='TAKE STRANGE ARTIFACT'}$('interaction-prompt').classList.toggle('visible',near);
+  camera.x=clamp(player.x-cw/2,0,W-cw);camera.y=clamp(player.y-ch/2,0,H-ch);updateUI();mapTimer+=dt;if(mapTimer>.25){drawMap();mapTimer=0}
+}
+function endGame(victory){dead=!victory;won=victory;gameStarted=false;$('end-eyebrow').textContent=victory?'CONTRACT COMPLETE':'FIELD REPORT';$('end-title').textContent=victory?'The Zone gave something back.':'The Zone claims another.';$('end-copy').textContent=victory?'Artifact recovered. The Skadovsk is already asking what you saw out there.':`You made it ${Math.floor(elapsed/60)} minutes. The Zone will keep moving.`;$('end-overlay').classList.remove('hidden')}
+function updateUI(){let signal=artifact.found?{x:420,y:1480}:artifact,d=dist(player,signal);$('mission-distance').textContent=d>1000?(d/1000).toFixed(1)+' KM TO '+(artifact.found?'CAMP':'SIGNAL'):Math.round(d)+' M TO '+(artifact.found?'CAMP':'SIGNAL');let a=Math.atan2(signal.y-player.y,signal.x-player.x);$('objective-arrow').style.transform=`rotate(${a*180/Math.PI}deg)`;$('health-bar').style.width=player.hp+'%';$('health-value').textContent=Math.ceil(player.hp);$('rad-bar').style.width=player.rad+'%';$('rad-value').textContent=String(Math.round(player.rad)).padStart(2,'0');$('ammo-current').textContent=player.ammo;$('ammo-reserve').textContent=player.reserve;$('rubles').textContent=player.ru.toLocaleString();$('status-label').textContent=player.hp<35?'CRITICAL':player.rad>50?'EXPOSED':'STABLE';$('status-label').style.color=player.hp<35?'#d27360':player.rad>50?'#d5a35b':'#a7bd78';let px=clamp(Math.floor(player.x/W*99),0,99),py=clamp(Math.floor(player.y/H*99),0,99);$('map-coords').textContent=`X ${String(px).padStart(2,'0')} / Y ${String(py).padStart(2,'0')}`}

