$('map-coords').textContent=`X ${String(px).padStart(2,'0')} / Y ${String(py).padStart(2,'0')}`}
function hash(x,y){let n=Math.sin(x*127.1+y*311.7+41.8)*43758.5453;return n-Math.floor(n)}
function drawGround(){ctx.fillStyle='#414c3c';ctx.fillRect(0,0,cw,ch);let sx=Math.floor(camera.x/80),sy=Math.floor(camera.y/80),ex=Math.ceil((camera.x+cw)/80),ey=Math.ceil((camera.y+ch)/80);for(let iy=sy;iy<=ey;iy++)for(let ix=sx;ix<=ex;ix++){let h=hash(ix,iy),x=ix*80-camera.x,y=iy*80-camera.y;ctx.fillStyle=h>.78?'#46513f':h<.18?'#3d493a':'#424d3c';ctx.fillRect(x,y,81,81);for(let i=0;i<4;i++){let px=x+hash(ix*4+i,iy*5)*76,py=y+hash(ix*7,iy*3+i)*76;ctx.fillStyle=h>.7?'rgba(130,131,84,.13)':'rgba(24,34,27,.13)';ctx.fillRect(px,py,2+hash(i,ix)*3,1)}}
  // Trampled paths weave between the outposts.
  ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='rgba(151,139,102,.21)';ctx.lineWidth=28;ctx.beginPath();ctx.moveTo(420-camera.x,1480-camera.y);ctx.bezierCurveTo(760-camera.x,1400-camera.y,850-camera.x,1130-camera.y,1230-camera.x,1100-camera.y);ctx.bezierCurveTo(1580-camera.x,1070-camera.y,1650-camera.x,780-camera.y,2120-camera.x,560-camera.y);ctx.stroke();ctx.strokeStyle='rgba(35,42,33,.25)';ctx.lineWidth=2;ctx.stroke();
  // Flooded lowland around the village.
  let water=ctx.createRadialGradient(2390-camera.x,1770-camera.y,80,2390-camera.x,1770-camera.y,440);water.addColorStop(0,'rgba(49,83,77,.53)');water.addColorStop(1,'rgba(55,83,73,0)');ctx.fillStyle=water;ctx.fillRect(1900-camera.x,1300-camera.y,900,850);
  for(let z of zones){let x=z.x-camera.x,y=z.y-camera.y;if(x<-300||x>cw+300||y<-300||y>ch+300)continue;let g=ctx.createRadialGradient(x,y,10,x,y,z.r);g.addColorStop(0,'rgba(25,33,26,.11)');g.addColorStop(1,'rgba(20,29,25,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,z.r,0,Math.PI*2);ctx.fill()}
}
function drawTree(t){let x=t.x-camera.x,y=t.y-camera.y;if(x<-35||x>cw+35||y<-35||y>ch+35)return;ctx.fillStyle='rgba(12,19,14,.32)';ctx.beginPath();ctx.ellipse(x+5,y+7,t.r*1.1,t.r*.72,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.t>.55?'#273a2c':'#304331';ctx.beginPath();ctx.arc(x,y,t.r,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.t>.55?'#3d5337':'#43583a';ctx.beginPath();ctx.arc(x-3,y-3,t.r*.65,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(143,143,89,.25)';ctx.beginPath();ctx.arc(x-5,y-6,t.r*.23,0,Math.PI*2);ctx.fill()}
function drawBuilding(b){let x=b.x-camera.x,y=b.y-camera.y;if(x<-200||x>cw+200||y<-150||y>ch+150)return;ctx.save();ctx.translate(x,y);ctx.rotate(b.r);let colors=['#55574a','#626252','#4f564a'];ctx.fillStyle='rgba(9,13,10,.4)';ctx.fillRect(-b.w/2+8,-b.h/2+9,b.w,b.h);ctx.fillStyle=colors[b.c];ctx.fillRect(-b.w/2,-b.h/2,b.w,b.h);ctx.fillStyle='rgba(167,152,112,.18)';ctx.fillRect(-b.w/2,-b.h/2,b.w,5);ctx.strokeStyle='rgba(23,29,24,.5)';ctx.lineWidth=2;ctx.strokeRect(-b.w/2,-b.h/2,b.w,b.h);ctx.fillStyle='#30362e';ctx.fillRect(-b.w*.17,-b.h/2+9,b.w*.34,b.h*.25);ctx.fillStyle='rgba(194,175,122,.24)';ctx.fillRect(-b.w/2+8,b.h*.17,12,8);ctx.restore()}
function drawRail(){ctx.save();ctx.strokeStyle='rgba(47,51,43,.9)';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(1880-camera.x,310-camera.y);ctx.lineTo(1980-camera.x,445-camera.y);ctx.lineTo(2120-camera.x,585-camera.y);ctx.lineTo(2260-camera.x,710-camera.y);ctx.stroke();ctx.strokeStyle='rgba(151,143,106,.7)';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(1875-camera.x,310-camera.y);ctx.lineTo(1975-camera.x,445-camera.y);ctx.lineTo(2115-camera.x,585-camera.y);ctx.lineTo(2255-camera.x,710-camera.y);ctx.moveTo(1885-camera.x,310-camera.y);ctx.lineTo(1985-camera.x,445-camera.y);ctx.lineTo(2125-camera.x,585-camera.y);ctx.lineTo(2265-camera.x,710-camera.y);ctx.stroke();for(let i=0;i<25;i++){let t=i/24,x=mix(1880,2260,t)-camera.x,y=mix(310,710,t)-camera.y;ctx.strokeStyle='rgba(133,124,91,.62)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-7,y+6);ctx.lineTo(x+7,y-6);ctx.stroke()}ctx.restore()}
function drawLandmarks(){for(let z of zones){let x=z.x-camera.x,y=z.y-camera.y;if(x<-200||x>cw+200||y<-100||y>ch+100)continue;ctx.fillStyle='rgba(9,13,10,.63)';ctx.font='9px "DM Mono", monospace';ctx.letterSpacing='1px';ctx.fillText(z.name,x-z.name.length*2.7,y-z.r*.72)}for(let i=0;i<5;i++){let x=1200+i*80-camera.x,y=650+i*32-camera.y;ctx.strokeStyle='rgba(179,185,111,.26)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,15+i%3*7,0,Math.PI*2);ctx.stroke()}}
function drawStash(s){if(s.searched)return;let x=s.x-camera.x,y=s.y-camera.y;ctx.fillStyle='rgba(0,0,0,.3)';ctx.fillRect(x-9,y+8,20,5);ctx.fillStyle='#65583d';ctx.fillRect(x-10,y-8,20,16);ctx.fillStyle='#a18d56';ctx.fillRect(x-8,y-7,16,3);ctx.strokeStyle='#2c3228';ctx.strokeRect(x-10,y-8,20,16);ctx.fillStyle=s.color;ctx.fillRect(x-2,y-2,4,4)}

